16	
17	/**
18	 * PauseOverlay — the dim + centered `ui_pause_panel` shown while the run is
19	 * paused (spec §6.3): Resume / Restart / Main-menu, plus a mute toggle. The
20	 * backdrop is interactive so it swallows taps (with `topOnly` input this also
21	 * blocks the HUD controls beneath it). Fully torn down via `destroy()`.
22	 */
23	export class PauseOverlay {
24	  private readonly scene: Phaser.Scene;
25	  private readonly objects: Phaser.GameObjects.GameObject[] = [];
26	  private readonly muteBtn: Phaser.GameObjects.Image;
27	  private readonly muteLabel: Phaser.GameObjects.Text;
28	  private readonly onMuteChanged: () => void;
29	
30	  constructor(scene: Phaser.Scene, cb: PauseOverlayCallbacks) {
31	    this.scene = scene;
