1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import {
4	  GAME_WIDTH,
5	  GAME_HEIGHT,
6	  GROUND_TOP_Y,
7	  HERO_X,
8	  MAX_HP,
9	  TICK_DAMAGE,
10	  OBSTACLE_DAMAGE,
11	  TABLET_HEAL,
12	  TABLET_SCORE,
13	  SCORE_SURVIVAL_PER_S,
14	  LEVEL_LENGTH,
15	  SPAWN_MARGIN_PX,
16	  RECYCLE_MARGIN_PX,
17	  HERO_BODY_HEIGHT,
18	  PARALLAX_FACTOR_FAR,
19	  PARALLAX_FACTOR_NEAR,
20	  PARALLAX_FACTOR_GROUND,
21	  PARALLAX_FACTOR_GRASS,
22	  HIT_SHAKE_MS,
23	  HIT_SHAKE_INTENSITY,
24	  HIT_FLASH_MS,
25	  RESULTS_HANDOFF_DELAY_MS,
26	  DEPTH,
27	} from '../config/gameConfig';
28	import { KEYS } from '../config/assetManifest';
29	import { track, type FinishGameParams } from '../analytics/track';
30	import { HeroDog } from '../entities/HeroDog';
31	import { FinishLine } from '../entities/FinishLine';
32	import { RunnerEntity } from '../entities/RunnerEntity';
33	import { DifficultyCurve } from '../systems/DifficultyCurve';
34	import { Spawner } from '../systems/Spawner';
35	import { Hud } from '../ui/Hud';
36	import { PauseOverlay } from '../ui/PauseOverlay';
37	import { GameEvents } from './gameEvents';
38	import { playSfx, Sfx, playMusic, pauseMusic, resumeMusic, stopMusic, Music } from '../systems/audio';
39	
40	// Re-export the event contract so subscribers can import it "from GameScene"
41	// (the canonical name) OR from the standalone module that breaks the Hud↔Scene
42	// import cycle. Both point at the same const.
43	export { GameEvents } from './gameEvents';
44	
45	/**
46	 * GameScene — the real, finite core run loop (spec §3, §5.2, §8.3).
47	 *
48	 * The hero is pinned at HERO_X and only moves vertically; the WORLD scrolls past
49	 * (parallax tileSprites + object-pooled entities driven by the DifficultyCurve).
50	 * Fires `start_game` on entry and `finish_game` on Victory (finish line) or Game
51	 * Over (0 HP), then hands the SAME {result, score, duration_s} payload to
52	 * ResultsScene.
53	 *
54	 * The scene is purely the MODEL: it owns run state and EMITS `GameEvents` on
55	 * `scene.events`; the Hud/PauseOverlay are the VIEW and only subscribe. Audio is
56	 * fired at the same choke points as the events (jump/hit/pickup/armor/win/lose).
57	 */
58	export class GameScene extends Phaser.Scene {
59	  private hero!: HeroDog;
60	  private curve!: DifficultyCurve;
61	  private spawner!: Spawner;
62	  private finishLine!: FinishLine;
63	  private hud!: Hud;
64	  private pauseOverlay: PauseOverlay | undefined;
65	
66	  // Parallax layers.
67	  private bgFar!: Phaser.GameObjects.TileSprite;
68	  private bgNear!: Phaser.GameObjects.TileSprite;
69	  private groundTile!: Phaser.GameObjects.TileSprite;
70	  private fgGrass!: Phaser.GameObjects.TileSprite;
71	
72	  // Run state.
73	  private distance = 0;
74	  private elapsedMs = 0;
75	  private tabletScore = 0;
76	  private score = 0;
77	  private finished = false;
78	  private finishSpawned = false;
79	  private paused = false;
80	
81	  // Change-tracking so HUD events only fire on transitions.
82	  private lastHp = MAX_HP;
83	  private lastScore = 0;
84	  private lastArmorActive = false;
85	
86	  private readonly spawnX = GAME_WIDTH + SPAWN_MARGIN_PX;
87	  private readonly recycleX = -RECYCLE_MARGIN_PX;
88	  /** Distance the hero covers while a right-edge spawn scrolls in to reach it. */
89	  private readonly approach = GAME_WIDTH + SPAWN_MARGIN_PX - HERO_X;
90	
91	  constructor() {
92	    super({ key: SceneKey.Game });
93	  }
94	
95	  create(): void {
96	    this.resetState();
97	    this.buildParallax();
98	    this.buildGroundAndHero();
99	    this.buildSystems();
100	    this.buildFinishLine();
101	    this.registerCollisions();
102	    this.buildHud();
103	    this.buildInput();
104	
105	    // A round has begun (spec §5.2).
106	    track('start_game');
107	    this.events.emit(GameEvents.runStart);
108	    playMusic(this, Music.game);
109	
110	    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.cleanup, this);
111	  }
112	
113	  // ── Public read hooks (HUD/audio can poll these for initial state) ─────────
114	  get liveHp(): number {
115	    return this.hero.hp;
116	  }
117	  get liveScore(): number {
118	    return this.score;
119	  }
120	  get liveProgress(): number {
121	    return this.curve.progress(this.distance);
122	  }
123	
124	  // ── Build steps ─────────────────────────────────────────────────────────────
125	  private resetState(): void {
126	    this.distance = 0;
127	    this.elapsedMs = 0;
128	    this.tabletScore = 0;
129	    this.score = 0;
130	    this.finished = false;
131	    this.finishSpawned = false;
132	    this.paused = false;
133	    this.lastHp = MAX_HP;
134	    this.lastScore = 0;
135	    this.lastArmorActive = false;
136	  }
137	
138	  private buildParallax(): void {
139	    const cx = GAME_WIDTH / 2;
140	    this.bgFar = this.add
141	      .tileSprite(cx, GAME_HEIGHT / 2, GAME_WIDTH, GAME_HEIGHT, KEYS.park_bg_far)
142	      .setDepth(DEPTH.bgFar);
143	    this.bgNear = this.add
144	      .tileSprite(cx, GROUND_TOP_Y, GAME_WIDTH, 360, KEYS.park_bg_near)
145	      .setOrigin(0.5, 1)
146	      .setDepth(DEPTH.bgNear);
147	    this.groundTile = this.add
148	      .tileSprite(cx, GROUND_TOP_Y, GAME_WIDTH, GAME_HEIGHT - GROUND_TOP_Y, KEYS.ground_tile)
149	      .setOrigin(0.5, 0)
150	      .setDepth(DEPTH.ground);
151	    this.fgGrass = this.add
152	      .tileSprite(cx, GAME_HEIGHT, GAME_WIDTH, 140, KEYS.park_fg_grass)
153	      .setOrigin(0.5, 1)
154	      .setDepth(DEPTH.grass);
155	  }
156	
157	  private buildGroundAndHero(): void {
158	    this.hero = new HeroDog(this, HERO_X, GROUND_TOP_Y);
159	    this.hero.setDepth(DEPTH.hero);
160	    this.hero.auraSprite.setDepth(DEPTH.aura);
161	
162	    // Invisible static floor so the hero's jump arc lands cleanly.
163	    const ground = this.add
164	      .rectangle(GAME_WIDTH / 2, GROUND_TOP_Y, GAME_WIDTH, GAME_HEIGHT - GROUND_TOP_Y, 0x000000, 0)
165	      .setOrigin(0.5, 0);
166	    this.physics.add.existing(ground, true);
167	    this.physics.add.collider(this.hero, ground);
168	  }
169	
170	  private buildSystems(): void {
171	    this.curve = new DifficultyCurve();
172	    this.spawner = new Spawner(this, this.curve, GROUND_TOP_Y, this.spawnX, this.recycleX);
173	  }
174	
175	  private buildFinishLine(): void {
176	    this.finishLine = new FinishLine(this);
177	    this.finishLine.setDepth(DEPTH.entity);
178	    this.add.existing(this.finishLine);
179	    this.physics.add.existing(this.finishLine);
180	    this.finishLine.recycle(); // hidden until it's queued near LEVEL_LENGTH
181	  }
182	
183	  private registerCollisions(): void {
184	    // Ticks: damage; when armored, the tick is CONSUMED for a powerful feel (§3.7).
185	    this.physics.add.overlap(
186	      this.hero,
187	      this.spawner.tickPool,
188	      (_h, obj) => this.onTick(obj as RunnerEntity),
189	      undefined,
190	      this,
191	    );
192	    // Bush/puddle: damage; ignored (not consumed) while invulnerable.
193	    this.physics.add.overlap(
194	      this.hero,
195	      this.spawner.obstaclePools,
196	      (_h, obj) => this.onObstacle(obj as RunnerEntity),
197	      undefined,
198	      this,
199	    );
200	    // Tablet: +score & +1 HP (capped).
201	    this.physics.add.overlap(
202	      this.hero,
203	      this.spawner.tabletPool,
204	      (_h, obj) => this.onTablet(obj as RunnerEntity),
205	      undefined,
206	      this,
207	    );
208	    // Armor: activate timed invulnerability + burst VFX.
209	    this.physics.add.overlap(
210	      this.hero,
211	      this.spawner.armorPool,
212	      (_h, obj) => this.onArmor(obj as RunnerEntity),
213	      undefined,
214	      this,
215	    );
216	    // Finish line: Victory.
217	    this.physics.add.overlap(this.hero, this.finishLine, () => this.endRun('win'), undefined, this);
218	  }
219	
220	  private buildHud(): void {
221	    this.hud = new Hud(
222	      this,
223	      { onPause: () => this.pauseGame() },
224	      { hp: this.liveHp, score: this.liveScore, progress: this.liveProgress },
225	    );
226	  }
227	
228	  private buildInput(): void {
229	    // The WHOLE canvas is the jump zone (spec §3.2 / §10.4), EXCEPT the HUD
230	    // controls: a tap that lands on an interactive object (pause/mute) must not
231	    // also jump, and no tap jumps while paused or after the run has ended.
232	    this.input.on(Phaser.Input.Events.POINTER_DOWN, this.onPointerDown, this);
233	    this.input.keyboard?.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE).on('down', this.onJumpKey, this);
234	  }
235	
236	  // ── Input handlers ─────────────────────────────────────────────────────────
237	  private onPointerDown(pointer: Phaser.Input.Pointer): void {
238	    if (this.paused || this.finished) return;
239	    // Taps on interactive HUD controls (pause/mute) are handled by those objects;
240	    // they must NOT also trigger a jump.
241	    if (this.input.hitTestPointer(pointer).length > 0) return;
242	    this.tryJump();
243	  }
244	
245	  private onJumpKey(): void {
246	    if (this.paused || this.finished) return;
247	    this.tryJump();
248	  }
249	
250	  private tryJump(): void {
251	    if (this.hero.jump()) playSfx(this, Sfx.jump);
252	  }
253	
254	  // ── Per-frame loop ────────────────────────────────────────────────────────────
255	  override update(_time: number, delta: number): void {
256	    if (this.finished || this.paused) return;
257	
258	    const dt = delta / 1000;
259	    this.elapsedMs += delta;
260	
261	    const progress = this.curve.progress(this.distance);
262	    const worldSpeed = this.curve.speed(progress);
263	    this.distance += worldSpeed * dt;
264	
265	    this.scrollParallax(worldSpeed, dt);
266	    this.spawner.update(this.distance, worldSpeed, progress);
267	    this.updateFinishLine(worldSpeed);
268	
269	    // Drive hero animation/armor timing off the SCENE clock so it freezes exactly
270	    // with the pause overlay (this.time.paused) and resumes bit-for-bit.
271	    const now = this.time.now;
272	    this.hero.tick(now);
273	    this.updateScore();
274	    this.syncHp();
275	    this.events.emit(GameEvents.progress, progress);
276	    this.emitArmor(now);
277	
278	    // Deterministic Victory: the finish line has reached the hero.
279	    if (this.finishSpawned && this.finishLine.active && this.finishLine.x <= HERO_X) {
280	      this.endRun('win');
281	    }
282	  }
283	
284	  private scrollParallax(worldSpeed: number, dt: number): void {
285	    this.bgFar.tilePositionX += worldSpeed * PARALLAX_FACTOR_FAR * dt;
286	    this.bgNear.tilePositionX += worldSpeed * PARALLAX_FACTOR_NEAR * dt;
287	    this.groundTile.tilePositionX += worldSpeed * PARALLAX_FACTOR_GROUND * dt;
288	    this.fgGrass.tilePositionX += worldSpeed * PARALLAX_FACTOR_GRASS * dt;
289	  }
290	
291	  private updateFinishLine(worldSpeed: number): void {
292	    if (!this.finishSpawned) {
293	      if (this.distance >= LEVEL_LENGTH - this.approach) {
294	        this.finishLine.spawn(this.spawnX, GROUND_TOP_Y);
295	        this.finishSpawned = true;
296	        this.spawner.stopSpawning(); // nothing spawns past the finish (§3.9)
297	      }
298	      return;
299	    }
300	    if (this.finishLine.active) this.finishLine.setVelocityX(-worldSpeed);
301	  }
302	
303	  // ── HUD event emitters (view-agnostic; the Hud subscribes) ─────────────────
304	  private updateScore(): void {
305	    const survival = Math.floor((this.elapsedMs / 1000) * SCORE_SURVIVAL_PER_S);
306	    this.score = this.tabletScore + survival;
307	    if (this.score !== this.lastScore) {
308	      this.events.emit(GameEvents.score, this.score);
309	      this.lastScore = this.score;
310	    }
311	  }
312	
313	  private syncHp(): void {
314	    const hp = this.hero.hp;
315	    if (hp !== this.lastHp) {
316	      this.events.emit(GameEvents.hp, hp);
317	      this.lastHp = hp;
318	    }
319	  }
320	
321	  private emitArmor(time: number): void {
322	    const active = this.hero.isArmored(time);
323	    if (active !== this.lastArmorActive) {
324	      this.events.emit(GameEvents.armor, { active, remainingMs: this.hero.armorRemaining(time) });
325	      this.lastArmorActive = active;
326	    }
327	  }
328	
329	  // ── Collision handlers ─────────────────────────────────────────────────────────
330	  private onTick(tick: RunnerEntity): void {
331	    if (this.finished || !tick.active) return;
332	    const time = this.time.now;
333	    if (this.hero.isArmored(time)) {
334	      tick.recycle(); // consumed by the shield — feels powerful (§3.7)
335	      return;
336	    }
337	    if (this.hero.isInvulnerable(time)) return; // mid i-frame — ignore, don't consume
338	    if (this.hero.takeHit(time, TICK_DAMAGE)) {
339	      tick.recycle();
340	      this.onHeroDamaged();
341	    }
342	  }
343	
344	  private onObstacle(obstacle: RunnerEntity): void {
345	    if (this.finished || !obstacle.active) return;
346	    const time = this.time.now;
347	    if (this.hero.isInvulnerable(time)) return; // armored or i-frame → no damage
348	    if (this.hero.takeHit(time, OBSTACLE_DAMAGE)) {
349	      this.onHeroDamaged(); // the dog bumps it; obstacle keeps scrolling
350	    }
351	  }
352	
353	  private onTablet(tablet: RunnerEntity): void {
354	    if (this.finished || !tablet.active) return;
355	    tablet.recycle();
356	    this.tabletScore += TABLET_SCORE;
357	    this.hero.heal(TABLET_HEAL);
358	    this.syncHp();
359	    playSfx(this, Sfx.tablet);
360	  }
361	
362	  private onArmor(armor: RunnerEntity): void {
363	    if (this.finished || !armor.active) return;
364	    armor.recycle();
365	    this.hero.activateArmor(this.time.now);
366	    this.spawnArmorBurst();
367	    playSfx(this, Sfx.armor);
368	  }
369	
370	  private onHeroDamaged(): void {
371	    this.cameras.main.shake(HIT_SHAKE_MS, HIT_SHAKE_INTENSITY);
372	    this.cameras.main.flash(HIT_FLASH_MS, 200, 60, 60);
373	    this.syncHp();
374	    playSfx(this, Sfx.hit);
375	    if (this.hero.hp <= 0) this.endRun('lose');
376	  }
377	
378	  /** One-shot pickup burst VFX (rare — not pooled; tween-then-destroy). */
379	  private spawnArmorBurst(): void {
380	    const burst = this.add
381	      .image(this.hero.x, this.hero.y - HERO_BODY_HEIGHT * 0.55, KEYS.vfx_armor_burst)
382	      .setDepth(DEPTH.aura);
383	    this.tweens.add({
384	      targets: burst,
385	      scale: { from: 0.5, to: 1.4 },
386	      alpha: { from: 1, to: 0 },
387	      duration: 380,
388	      ease: 'Quad.out',
389	      onComplete: () => burst.destroy(),
390	    });
391	  }
392	
393	  // ── Pause loop ───────────────────────────────────────────────────────────────
394	  private pauseGame(): void {
395	    if (this.paused || this.finished) return;
396	    this.paused = true;
397	    // Freeze EVERYTHING: physics bodies, all tweens, the scene clock (which also
398	    // owns the spawner cadence + the hero's armor/i-frame timing), and music.
399	    this.physics.world.pause();
400	    this.tweens.pauseAll();
401	    this.time.paused = true;
402	    pauseMusic();
403	
404	    this.pauseOverlay = new PauseOverlay(this, {
405	      onResume: () => this.resumeGame(),
406	      onRestart: () => this.restartRun(),
407	      onMenu: () => this.quitToMenu(),
408	      onMuteChanged: () => this.hud.syncMute(),
409	    });
410	  }
411	
412	  private resumeGame(): void {
413	    if (!this.paused) return;
414	    this.exitPauseState();
415	    resumeMusic();
416	  }
417	
418	  private restartRun(): void {
419	    // Leave no frozen physics/clock behind, drop the music so create() starts it
420	    // fresh, then rebuild the whole scene.
421	    this.exitPauseState();
422	    stopMusic();
423	    this.scene.restart();
424	  }
425	
426	  private quitToMenu(): void {
427	    this.exitPauseState();
428	    stopMusic();
429	    this.scene.start(SceneKey.Menu);
430	  }
431	
432	  /** Tear down the overlay and unfreeze the world (shared by every pause exit). */
433	  private exitPauseState(): void {
434	    this.pauseOverlay?.destroy();
435	    this.pauseOverlay = undefined;
436	    this.tweens.resumeAll();
437	    this.physics.world.resume();
438	    this.time.paused = false;
439	    this.paused = false;
440	  }
441	
442	  // ── Termination ────────────────────────────────────────────────────────────────
443	  private endRun(result: 'win' | 'lose'): void {
444	    if (this.finished) return;
445	    this.finished = true;
446	
447	    if (result === 'win') {
448	      this.hero.victory();
449	      playSfx(this, Sfx.victory);
450	    } else {
451	      this.hero.defeat();
452	      playSfx(this, Sfx.defeat);
453	    }
454	    stopMusic(); // the run is over — let the sting land over silence
455	
456	    this.spawner.freeze();
457	    if (this.finishLine.active) this.finishLine.setVelocityX(0);
458	
459	    const payload: FinishGameParams = {
460	      result,
461	      score: this.score,
462	      duration_s: Math.round(this.elapsedMs / 1000),
463	    };
464	    track('finish_game', payload);
465	    this.events.emit(GameEvents.runEnd, payload);
466	
467	    // Let the win/lose pose read, then hand off with the EXACT payload.
468	    this.time.delayedCall(RESULTS_HANDOFF_DELAY_MS, () => {
469	      this.scene.start(SceneKey.Results, payload);
470	    });
471	  }
472	
473	  private cleanup(): void {
474	    // Tweens/timers/display objects are scene-scoped and auto-destroyed; destroy the
475	    // pools + overlay explicitly so re-entering Game (play again) never leaks or
476	    // double-fires. (The Hud self-destructs on the same SHUTDOWN event.)
477	    this.pauseOverlay?.destroy();
478	    this.pauseOverlay = undefined;
479	    this.spawner.destroy();
480	  }
481	}
