1	import Phaser from 'phaser';
2	import { KEYS } from '../config/assetManifest';
3	import { DEPTH, PAUSE, GAME_WIDTH, GAME_HEIGHT, MIN_TAP_TARGET_PX } from '../config/gameConfig';
4	import { t } from '../i18n/strings';
5	import { createButton, enlargeHitArea } from './Button';
6	import { AudioManager } from '../systems/AudioManager';
7	import { playSfx, Sfx } from '../systems/audio';
8	
9	export interface PauseOverlayCallbacks {
10	  onResume: () => void;
11	  onRestart: () => void;
12	  onMenu: () => void;
13	  /** Called after mute is toggled here, so the HUD can repaint its own icon. */
14	  onMuteChanged: () => void;
15	}
16	
17	/**
18	 * PauseOverlay — the dim + centered `ui_pause_panel` shown while the run is
19	 * paused (spec §6.3): Resume / Restart / Main-menu, plus a mute toggle. The
20	 * backdrop is interactive so it swallows taps (with `topOnly` input this also
21	 * blocks the HUD controls beneath it). Fully torn down via `destroy()`.
22	 */
23	export class PauseOverlay {
24	  private readonly scene: Phaser.Scene;
25	  private readonly objects: Phaser.GameObjects.GameObject[] = [];
26	  private readonly muteBtn: Phaser.GameObjects.Image;
27	  private readonly muteLabel: Phaser.GameObjects.Text;
28	  private readonly onMuteChanged: () => void;
29	
30	  constructor(scene: Phaser.Scene, cb: PauseOverlayCallbacks) {
31	    this.scene = scene;
32	    this.onMuteChanged = cb.onMuteChanged;
33	    const cx = GAME_WIDTH / 2;
34	    const cy = GAME_HEIGHT / 2;
35	
36	    // Dim backdrop that also swallows taps to the frozen game beneath.
37	    const backdrop = scene.add
38	      .rectangle(cx, cy, GAME_WIDTH, GAME_HEIGHT, PAUSE.backdropColor, PAUSE.backdropAlpha)
39	      .setDepth(DEPTH.pauseBackdrop)
40	      .setInteractive();
41	    this.objects.push(backdrop);
42	
43	    const panel = scene.add.image(cx, cy, KEYS.ui_pause_panel).setDepth(DEPTH.pausePanel);
44	    this.objects.push(panel);
45	
46	    const title = scene.add
47	      .text(cx, cy + PAUSE.titleOffsetY, t('pause_title'), {
48	        fontFamily: 'system-ui, sans-serif',
49	        fontSize: PAUSE.titleFontSize,
50	        fontStyle: 'bold',
51	        color: PAUSE.titleColor,
52	      })
53	      .setOrigin(0.5)
54	      .setDepth(DEPTH.pauseContent);
55	    this.objects.push(title);
56	
57	    this.objects.push(this.makeButton(cx, cy + PAUSE.resumeOffsetY, t('pause_resume'), cb.onResume));
58	    this.objects.push(this.makeButton(cx, cy + PAUSE.restartOffsetY, t('pause_restart'), cb.onRestart));
59	    this.objects.push(this.makeButton(cx, cy + PAUSE.menuOffsetY, t('pause_menu'), cb.onMenu));
60	
61	    // Mute toggle (mirrors the HUD control; shares the persisted state).
62	    this.muteBtn = scene.add
63	      .image(cx + PAUSE.muteOffsetX, cy + PAUSE.muteOffsetY, this.muteTexture())
64	      .setDepth(DEPTH.pauseContent);
65	    enlargeHitArea(this.muteBtn, MIN_TAP_TARGET_PX); // full-icon + comfortable tap target (§10.4)
66	    this.muteBtn.on(Phaser.Input.Events.POINTER_UP, this.onMuteTap, this);
67	    this.objects.push(this.muteBtn);
68	
69	    this.muteLabel = scene.add
70	      .text(cx + PAUSE.muteOffsetX, cy + PAUSE.muteOffsetY + PAUSE.muteLabelOffsetY, this.muteLabelText(), {
71	        fontFamily: 'system-ui, sans-serif',
72	        fontSize: PAUSE.muteLabelFontSize,
73	        color: PAUSE.muteLabelColor,
74	      })
75	      .setOrigin(0.5, 0)
76	      .setDepth(DEPTH.pauseContent);
77	    this.objects.push(this.muteLabel);
78	
79	    // Quick fade-in (created AFTER the scene paused its tweens, so it still runs).
80	    scene.tweens.add({
81	      targets: this.objects,
82	      alpha: { from: 0, to: 1 },
83	      duration: PAUSE.fadeInMs,
84	      ease: 'Quad.out',
85	    });
86	  }
87	
88	  destroy(): void {
89	    for (const obj of this.objects) obj.destroy();
90	    this.objects.length = 0;
91	  }
92	
93	  private makeButton(x: number, y: number, label: string, onClick: () => void): Phaser.GameObjects.Container {
94	    return createButton(this.scene, {
95	      x,
96	      y,
97	      label,
98	      width: PAUSE.buttonWidth,
99	      height: PAUSE.buttonHeight,
100	      onClick: () => {
101	        playSfx(this.scene, Sfx.ui);
102	        onClick();
103	      },
104	    }).setDepth(DEPTH.pauseContent);
105	  }
106	
107	  private onMuteTap(): void {
108	    AudioManager.toggle(this.scene.sound);
109	    this.muteBtn.setTexture(this.muteTexture());
110	    this.muteLabel.setText(this.muteLabelText());
111	    playSfx(this.scene, Sfx.ui);
112	    this.onMuteChanged();
113	  }
114	
115	  private muteTexture(): string {
116	    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
117	  }
118	
119	  private muteLabelText(): string {
120	    return AudioManager.isMuted() ? t('menu_sound_off') : t('menu_sound_on');
121	  }
122	}
